-- 3. Dubbla scheman: avsluta de automatiskt skapade
with dup as (select id from public.recurring_schedules where id::text like any (array['e04f8710%','0e18c349%','f34d27d2%']) and notes like 'Skapat vid avtalskarteuppläggning 2026-09-17%' and status = 'active'),
  fut as (select s.id, s.case_id from public.station_inspection_sessions s where s.recurring_schedule_id in (select id from dup) and s.status = 'scheduled' and s.scheduled_at >= now()),
  c as (update public.cases set status = 'Borttaget' where id in (select case_id from fut) and status = 'Bokad' and updated_at < created_at + interval '5 minutes' returning id),
  ss as (update public.station_inspection_sessions set status = 'cancelled' where id in (select f.id from fut f where f.case_id in (select id from c)) returning id)
update public.recurring_schedules set status = 'cancelled', updated_at = now() where id in (select id from dup);

alter table public.cases enable trigger cases_technician_notifications;

commit;
